// Line icons, matching the brand's single-weight line-drawing style.
//
// Inline SVG strings rather than an icon font or sprite sheet: they inherit
// currentColor, need no extra request, and there are few enough of them that a
// sprite would be ceremony. Every icon is a 24x24 viewBox so they line up
// wherever they are dropped.
//
// `filled` variants exist only for the tab bar, where the active tab must differ
// by shape and not only by colour (docs/01-design-system.md).

const svg = (body, { size = 24, fill = 'none' } = {}) =>
  `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="${fill}" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${body}</svg>`;

const solid = (body) =>
  `<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">${body}</svg>`;

